def build_presentation():
    prs = Presentation()
    prs.slide_width = Inches(13.333)
    prs.slide_height = Inches(7.5)
    bg = RGBColor(245, 248, 250)
    blue = RGBColor(31, 78, 121)
    orange = RGBColor(198, 89, 17)

    for i, (title, bullets) in enumerate(slides):
        layout = prs.slide_layouts[6]
        slide = prs.slides.add_slide(layout)
        fill = slide.background.fill
        fill.solid()
        fill.fore_color.rgb = bg

        title_box = slide.shapes.add_textbox(Inches(0.55), Inches(0.35), Inches(12.2), Inches(0.8))
        tf = title_box.text_frame
        tf.clear()
        p = tf.paragraphs[0]
        p.text = title
        p.font.bold = True
        p.font.size = PptPt(34 if i == 0 else 30)
        p.font.name = "Arial"
        p.font.color.rgb = blue

        line = slide.shapes.add_shape(1, Inches(0.55), Inches(1.25), Inches(12.2), Inches(0.04))
        line.fill.solid()
        line.fill.fore_color.rgb = orange
        line.line.fill.background()

        body = slide.shapes.add_textbox(Inches(0.9), Inches(1.55), Inches(11.8), Inches(5.35))
        tf = body.text_frame
        tf.word_wrap = True
        tf.clear()
        for j, bullet in enumerate(bullets):
            if j == 0:
                p = tf.paragraphs[0]
            else:
                p = tf.add_paragraph()
            p.text = bullet
            p.level = 0
            p.font.name = "Arial"
            p.font.size = PptPt(25 if i != 0 else 27)
            p.font.color.rgb = RGBColor(40, 40, 40)
            p.space_after = PptPt(10)

        footer = slide.shapes.add_textbox(Inches(0.55), Inches(7.0), Inches(12.2), Inches(0.28))
        ft = footer.text_frame
        ft.clear()
        p = ft.paragraphs[0]
        p.text = f"{i + 1}/10"
        p.alignment = PP_ALIGN.RIGHT
        p.font.size = PptPt(12)
        p.font.color.rgb = RGBColor(100, 100, 100)

    prs.save(PPTX)


